mapper.select:
SELECT * FROM system_soft_container 
WHERE system_soft_container_docker_id = #{dockerContainerId}
LIMIT 1

SELECT * FROM system_soft_container 
WHERE system_soft_container_name = #{containerName}
LIMIT 1

SELECT * FROM system_soft_container 
WHERE system_soft_id = #{softId} 
AND system_server_id = #{serverId}

SELECT * FROM system_soft_container 
WHERE system_server_id = #{serverId} 
AND system_soft_container_status = #{containerStatus}

SELECT system_soft_container_status as status, COUNT(*) as count FROM system_soft_container
AND system_server_id = #{serverId}
GROUP BY system_soft_container_status

SELECT COUNT(*) 
FROM system_soft_container 
WHERE system_soft_container_status = #{containerStatus}

SELECT COUNT(*) 
FROM system_soft_container 
WHERE system_server_id = #{serverId} 
AND system_soft_container_status = #{containerStatus}

SELECT COUNT(*) 
FROM system_soft_container 
WHERE system_soft_id = #{softId}

SELECT COUNT(*) 
FROM system_soft_container 
WHERE system_server_id = #{serverId}

SELECT COUNT(*) 
FROM system_soft_container 
WHERE system_soft_container_name = #{containerName}
AND system_server_id = #{serverId}

    AND system_soft_container_id != #{excludeId}

SELECT COUNT(*) 
FROM system_soft_container 
WHERE system_soft_container_ports LIKE CONCAT('%', #{hostPort}, '%')
AND system_server_id = #{serverId}

    AND system_soft_container_id != #{excludeId}
